using HRM.Models;using HRM.Models.Recruitment;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace HRM.Api.Data.EntityConfigurations;
public sealed class RecruitmentScreeningMapping:IEntityTypeConfiguration<RecruitmentScreeningDecision>,IEntityTypeConfiguration<RecruitmentPanelConflictDeclaration>{public void Configure(EntityTypeBuilder<RecruitmentScreeningDecision>b){b.ToTable("RM_RecruitmentScreeningDecisions");b.HasKey(x=>x.Id);b.Property(x=>x.DecisionReason).HasMaxLength(2000).IsRequired();b.Property(x=>x.EvidenceSnapshotJson).HasMaxLength(16000).IsRequired();b.Property(x=>x.Version).IsConcurrencyToken();b.HasIndex(x=>x.RecruitmentApplicationId).IsUnique();b.HasIndex(x=>new{x.RecruitmentVacancyId,x.IsEligible,x.IsShortlisted});b.HasOne<RecruitmentApplication>().WithMany().HasForeignKey(x=>x.RecruitmentApplicationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<RecruitmentVacancy>().WithMany().HasForeignKey(x=>x.RecruitmentVacancyId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Organisation>().WithMany().HasForeignKey(x=>x.OrganisationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<OperationLog>().WithMany().HasForeignKey(x=>x.OperationLogId).OnDelete(DeleteBehavior.Restrict);}public void Configure(EntityTypeBuilder<RecruitmentPanelConflictDeclaration>b){b.ToTable("RM_RecruitmentPanelConflictDeclarations");b.HasKey(x=>x.Id);b.Property(x=>x.Declaration).HasMaxLength(2000).IsRequired();b.Property(x=>x.Mitigation).HasMaxLength(2000);b.Property(x=>x.Version).IsConcurrencyToken();b.HasIndex(x=>new{x.RecruitmentVacancyId,x.DeclaredByUserId}).IsUnique();b.HasOne<RecruitmentVacancy>().WithMany().HasForeignKey(x=>x.RecruitmentVacancyId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Organisation>().WithMany().HasForeignKey(x=>x.OrganisationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<OperationLog>().WithMany().HasForeignKey(x=>x.OperationLogId).OnDelete(DeleteBehavior.Restrict);}}
